          }
        }
      }
    } else {
      normalized = normalizeArgsForCodex(args);
    }
    return {
      id: callId,
      type: "function_call",
      status: item.status || "completed",
      call_id: callId,
      name,
      arguments: normalized,
      ...(item.namespace ? { namespace: item.namespace } : target ? { namespace: target.namespace } : {}),
