        return json({ error: { message } }, blocked);
      }
      if (request.method === "GET" && apiPath === "/v1/models") {
        const merged = mergeCatalog(config);
        return json({
          object: "list",
          data: merged.models.map((m) => ({
            id: m.slug || m.alias,
            object: "model",
            owned_by: "codextras",
            display_name: m.display_name || m.displayName || m.slug,
          })),
        });
      }
      if (request.method !== "POST") {
        return json({ error: { message: "method not allowed" } }, 405);
      }
      const rawBody = await request.arrayBuffer().catch(() => new ArrayBuffer(0));
      let payload;
      try {
        payload = JSON.parse(new TextDecoder().decode(rawBody));
      } catch {
        payload = undefined;
      }
      if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
        return json({ error: { message: "Request body must be a JSON object." } }, 400);
      }
      const inputs = Array.isArray(payload.input) ? payload.input : [];
      const compactionV2 =
        inputs.length > 0 && inputs[inputs.length - 1]?.type === "compaction_trigger";
      if (apiPath === "/v1/responses/compact" || compactionV2) {
        return handleCompaction(request, payload, apiPath, rawBody);
      }
      if (apiPath === "/v1/responses") {
        return handleTurn(request, payload, apiPath, rawBody);
      }
      return json({ error: { message: "unknown route " + apiPath } }, 404);
    },
  });
}

async function handleTurn(request, payload, apiPath, rawBody) {
  const model = findModel(payload.model, loadConfig());
  if (!model) {
    // Undeclared models are native OpenAI models: pass the request through.
    return forwardNative(request, apiPath, rawBody);
  }
  const config = loadConfig();
  const provider = providerFor(model, config);
  if (!provider) {
    return json({ error: { message: "No provider configured for " + model.alias } }, 500);
  }
  const isResponses = isResponsesModel(model, provider);
  if (isResponses) {
    const customTools = supportsResponsesCustomTools(model, provider);
    const { tools: rawTools, names, customNames } = flattenToolsForResponses(payload.tools, {
      supportsCustomTools: customTools,
    });
    const tools = filterToolsByDisabled(rawTools, provider, model, isResponses);
    const input = buildResponsesInput({
      input: Array.isArray(payload.input) ? payload.input : [],
      model,
      supportsCustomTools: customTools,
    });
    const stream = payload.stream !== false;
    const body = buildResponsesBody({ payload, model, provider, input, tools, stream });
    const requestBytes = Buffer.byteLength(JSON.stringify(body), "utf8");
    const url = responsesUrl(provider);
    const headers = providerHeaders(provider);
    debugLog({ dir: "req", wire: "responses", model: model.alias, upstreamModel: model.upstreamModel, isResponses, url, body: JSON.stringify(body).slice(0, 8000), toolsIn: Array.isArray(payload.tools) ? payload.tools.length : 0, inputIn: Array.isArray(payload.input) ? payload.input.length : 0, inputOut: input.length });
    let res;
    try {
      res = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
        signal: request.signal,
      });
    } catch (error) {
      if (request.signal.aborted) {
        debugLog({ dir: "aborted", wire: "responses", model: model.alias });
        return sseError("Request aborted by client", 499);
      }
      const message = error && error.message ? error.message : String(error);
      debugLog({ dir: "error", wire: "responses", model: model.alias, message, stream });
      return errorResponse(message, 502, stream);
    }
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      let message = "Upstream error " + res.status;
      try {
        const parsed = JSON.parse(text);
        if (parsed && parsed.error && parsed.error.message) message = parsed.error.message;
        else if (parsed && parsed.error) message = JSON.stringify(parsed.error);
        else if (text) message = text.slice(0, 3000);
      } catch {
        if (text) message = text.slice(0, 3000);
      }
      debugLog({ dir: "upstream_error", wire: "responses", model: model.alias, status: res.status, upstreamBody: text.slice(0, 8000), sentBody: JSON.stringify(body).slice(0, 8000), stream });
      return errorResponse(message, res.status, stream);
    }
    if (stream) {
      return streamResponsesTurn(res, {
        model: model.alias,
        requestBytes,
        toolNames: names,
        customNames,
      });
    }
    const upstreamJson = await res.json().catch(() => ({}));
    const mapped = transformResponsesJsonForCodex(upstreamJson, {
      toolNames: names,
      customNames,
      requestedModel: model.alias,
      requestBytes,
    });
    if (mapped && typeof mapped === "object" && !mapped.usage) {
      const { fallbackFrom, finalizeUsage } = await import("./usage.mjs");
      mapped.usage = finalizeUsage(undefined, fallbackFrom(requestBytes, JSON.stringify(mapped.output || "")));
    }
    return json(mapped);
  }
  const { tools: rawTools, names, customNames } = flattenTools(payload.tools);
  const tools = filterToolsByDisabled(rawTools, provider, model, isResponses);
  const messages = buildMessages({ input: payload.input || [], model });
  if (typeof payload.instructions === "string" && payload.instructions.trim()) {
    messages.unshift({ role: "system", content: payload.instructions });
  }
  const stream = payload.stream !== false;
  const body = buildChatBody({ payload, model, provider, messages, tools, stream });
  const requestBytes = Buffer.byteLength(JSON.stringify(body), "utf8");
  const url = chatUrl(provider);
  const headers = providerHeaders(provider);
  debugLog({ dir: "req", wire: "chat", model: model.alias, upstreamModel: model.upstreamModel, isResponses, url, body: JSON.stringify(body).slice(0, 8000), toolsIn: Array.isArray(payload.tools) ? payload.tools.length : 0, inputIn: Array.isArray(payload.input) ? payload.input.length : 0, messagesOut: messages.length });
  let res;
  try {
    res = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      signal: request.signal,
    });
  } catch (error) {
    if (request.signal.aborted) {
      debugLog({ dir: "aborted", wire: "chat", model: model.alias });
      return sseError("Request aborted by client", 499);
    }
    const message = error && error.message ? error.message : String(error);
    debugLog({ dir: "error", wire: "chat", model: model.alias, message, stream });
    return errorResponse(message, 502, stream);
  }
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    let message = "Upstream error " + res.status;
    try {
      const parsed = JSON.parse(text);
      if (parsed && parsed.error && parsed.error.message) message = parsed.error.message;
      else if (parsed && parsed.error) message = JSON.stringify(parsed.error).slice(0, 3000);
      else if (text) message = text.slice(0, 3000);
    } catch {
      if (text) message = text.slice(0, 3000);
    }
    debugLog({ dir: "upstream_error", wire: "chat", model: model.alias, status: res.status, upstreamBody: text.slice(0, 8000), sentBody: JSON.stringify(body).slice(0, 8000), stream });
    return errorResponse(message, res.status, stream);
  }
  if (stream) {
    return streamTurn(res, {
      model: model.alias,
      requestBytes,
      toolNames: names,
      customNames,
    });
  }
  const upstreamJson = await res.json().catch(() => ({}));
  return json(
    convertChatJsonToResponses({
      json: upstreamJson,
      requestedModel: model.alias,
      requestBytes,
      toolNames: names,
      customNames,
    }),
  );
}

async function handleCompaction(request, payload, apiPath, rawBody) {
  const config = loadConfig();
  const model = findModel(payload.model, config);
  if (!model) {
    return forwardNative(request, apiPath, rawBody);
  }
  const provider = providerFor(model, config);
  if (!provider) {
    return json({ error: { message: "No provider configured for " + model.alias } }, 500);
  }
  const bodyForBytes = JSON.stringify({
    model: model.alias,
    input: payload.input || [],
  });
  const requestBytes = Buffer.byteLength(bodyForBytes, "utf8");
  const result = await summarize({
    payload,
    model,
    provider,
    requestBytes,
    signal: request.signal,
  });
  if (!result.ok) {
    return json(result.payload, result.status);
  }
  const inputs = Array.isArray(payload.input) ? payload.input : [];
  const compactionV2 =
    inputs.length > 0 && inputs[inputs.length - 1]?.type === "compaction_trigger";
  if (compactionV2) {
    if (payload.stream === false) {
      const item = {
        type: "compaction",
        id: newId("cmp"),
        encrypted_content: encodeSummary(result.summary),
      };
      return json(compactionSnapshot(payload.model, item));
    }
    return new Response(writeCompactionSseEvents(payload.model, result.summary), {
      headers: SSE_HEADERS,
    });
  }
  return json({ output: compactOutputV1(result.input, result.summary) });
}

export function catalogFor(config) {
  return generateCatalog(config.models);
}

if (import.meta.main) {
  const config = loadConfig();
  const secret = loadSecret();
  const server = createServer(config, secret);
  console.log(
    "codextras listening on http://127.0.0.1:" +
      server.port +
      config.gateway.pathPrefix +
      "/<secret>/v1",
  );
}

import { appendFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { loadConfig, loadSecret, findModel, providerFor } from "./config.mjs";
import { LOG_PATH, STATE_DIR } from "./config.mjs";
import { generateCatalog } from "./catalog.mjs";
import {
  buildChatBody,
  buildResponsesBody,
  chatUrl,
  isResponsesModel,
  providerHeaders,
  responsesUrl,
  supportsResponsesCustomTools,
} from "./adapter.mjs";
import { buildMessages, buildResponsesInput, flattenTools, flattenToolsForResponses } from "./convert/request.mjs";
import { ChatStreamConverter, mapToolName } from "./convert/stream.mjs";
import { convertChatJsonToResponses } from "./convert/json.mjs";
import { toolCallItem, unwrapCustomToolArguments } from "./convert/tools.mjs";
import {
  compactOutputV1,
  compactionSnapshot,
  summarize,
  writeCompactionSseEvents,
} from "./compaction.mjs";
import { encodeSummary, newId, sseDone } from "./util.mjs";
import { forwardNative } from "./native.mjs";
import { mergeCatalog } from "./catalog.mjs";

const SSE_HEADERS = {
  "Content-Type": "text/event-stream; charset=utf-8",
  "Cache-Control": "no-cache",
  Connection: "keep-alive",
};

function debugLog(obj) {
  try {
    mkdirSync(path.dirname(LOG_PATH), { recursive: true });
    const line = JSON.stringify({ ts: new Date().toISOString(), ...obj }) + "\n";
    appendFileSync(LOG_PATH, line);
  } catch {}
}

function json(data, status) {
  return Response.json(data, { status: status || 200 });
}

function sseError(message, status) {
  const payload = JSON.stringify({ error: { message }, status });
  const body = `event: error\ndata: ${payload}\n\n${sseDone()}`;
  return new Response(body, { status, headers: SSE_HEADERS });
}

function errorResponse(message, status, stream) {
  if (stream) return sseError(message, status);
  return json({ error: { message } }, status);
}

function disabledToolTypes(provider, model) {
  const out = new Set();
  const lists = [
    provider && provider.quirks && provider.quirks.disabledTools,
    provider && provider.quirks && provider.quirks.disabled_tools,
    model && model.disabledTools,
    model && model.disabled_tools,
  ];
  for (const list of lists) {
    if (Array.isArray(list)) for (const name of list) if (typeof name === "string" && name) out.add(name);
  }
  return out;
}

function filterToolsByDisabled(tools, provider, model, isResponses) {
  const disabled = disabledToolTypes(provider, model);
  // Chat Completions cannot carry Responses builtins such as web_search.
  // This is a wire capability rule, not a model-name exception. Responses
  // keeps the native builtin when the declared model supports it.
  if (!isResponses) {
    disabled.add("web_search");
    disabled.add("web_search_2025_08_26");
  }
  if (model && model.supportsSearchTool === false) {
    disabled.add("web_search");
    disabled.add("web_search_2025_08_26");
  }
  if (disabled.size === 0) return tools;
  return (Array.isArray(tools) ? tools : []).filter(
    (tool) => !tool || typeof tool.type !== "string" || !disabled.has(tool.type),
  );
}

function apiPathFrom(url, prefix, secret) {
  const pathname = url.pathname;
  if (pathname === "/health" || pathname === "/health/liveliness") return "health";
  const expected = prefix + "/";
  if (!pathname.startsWith(expected)) return undefined;
  const rest = pathname.slice(expected.length);
  const slash = rest.indexOf("/");
  if (slash < 0) return undefined;
  const token = rest.slice(0, slash);
  if (token !== secret) return undefined;
  return rest.slice(slash);
}

function guard(request) {
  if (request.headers.get("origin") || request.headers.get("sec-fetch-site")) return 403;
  if (request.method === "POST") {
    const type = String(request.headers.get("content-type") || "")
      .split(";", 1)[0]
      .trim()
      .toLowerCase();
    if (type !== "application/json") return 415;
  }
  return null;
}

function contentEncodings(header) {
  if (!header) return [];
  return String(header)
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter((s) => s && s !== "identity");
}

function normalizeEncoding(token) {
  if (token === "x-gzip" || token === "gzip") return "gzip";
  if (token === "deflate") return "deflate";
  if (token === "deflate-raw") return "deflate-raw";
  if (token === "br" || token === "brotli" || token === "x-br") return "brotli";
  if (token === "zstd" || token === "zst" || token === "x-zstd") return "zstd";
  return token;
}

async function decompressOnce(bytes, format) {
  try {
    const ds = new DecompressionStream(format);
    const out = await new Response(new Blob([bytes]).stream().pipeThrough(ds)).arrayBuffer();
    return new Uint8Array(out);
  } catch (e) {
    if (format === "deflate") {
      try {
        const dsRaw = new DecompressionStream("deflate-raw");
        const out = await new Response(new Blob([bytes]).stream().pipeThrough(dsRaw)).arrayBuffer();
        return new Uint8Array(out);
      } catch {}
    }
    try {
      if (format === "gzip" && typeof Bun !== "undefined" && typeof Bun.gunzipSync === "function") {
        const out = Bun.gunzipSync(bytes);
        return out instanceof Uint8Array ? out : new Uint8Array(out);
      }
      if (format === "zstd" && typeof Bun !== "undefined" && typeof Bun.zstdDecompressSync === "function") {
        const out = Bun.zstdDecompressSync(bytes);
        return out instanceof Uint8Array ? out : new Uint8Array(out);
      }
      if (format === "brotli") {
        const { brotliDecompressSync } = await import("node:zlib");
        return new Uint8Array(brotliDecompressSync(Buffer.from(bytes)));
      }
      if (format === "deflate" || format === "deflate-raw") {
        const { inflateSync, inflateRawSync } = await import("node:zlib");
        try {
          return new Uint8Array(inflateSync(Buffer.from(bytes)));
        } catch {
          return new Uint8Array(inflateRawSync(Buffer.from(bytes)));
        }
      }
    } catch {}
    throw e;
  }
}

async function decodeBodyBytes(raw, header) {
  const bytes = raw instanceof Uint8Array ? raw : new Uint8Array(raw || []);
  if (bytes.byteLength === 0) return bytes;
  const tokens = contentEncodings(header);
  if (!tokens.length) return bytes;
  let out = bytes;
  for (let i = tokens.length - 1; i >= 0; i -= 1) {
    out = await decompressOnce(out, normalizeEncoding(tokens[i]));
  }
  return out;
}

async function* sseEvents(body) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let index;
    while ((index = buffer.indexOf("\n\n")) >= 0) {
      const block = buffer.slice(0, index);
      buffer = buffer.slice(index + 2);
      const data = block
        .split("\n")
        .map((line) => line.replace(/\r$/, ))
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).trimStart())
        .join("\n");
      if (data && data !== "[DONE]") {
        try {
          yield JSON.parse(data);
        } catch {
          // Ignore malformed SSE blocks; the stream continues.
        }
      }
    }
  }
  const data = buffer
    .split("\n")
    .map((line) => line.replace(/\r$/, ))
    .filter((line) => line.startsWith("data:"))
    .map((line) => line.slice(5).trimStart())
    .join("\n");
  if (data && data !== "[DONE]") {
    try {
      yield JSON.parse(data);
    } catch {
      // Ignore malformed trailing block.
    }
  }
}

async function streamTurn(upstream, { model, requestBytes, toolNames, customNames }) {
  const converter = new ChatStreamConverter({
    requestedModel: model,
    requestBytes,
    toolNames,
    customNames,
  });
  const encoder = new TextEncoder();
  let streamError = null;
  const stream = new ReadableStream({
    async start(controller) {
      controller.enqueue(encoder.encode(converter.initialEvents()));
      try {
        for await (const chunk of sseEvents(upstream.body)) {
          const events = converter.handleChunk(chunk);
          if (events) controller.enqueue(encoder.encode(events));
        }
      } catch (e) {
        streamError = e && e.message ? e.message : String(e);
        debugLog({ dir: "stream_error", wire: "chat", model, message: streamError });
      }
      if (streamError) {
        controller.enqueue(encoder.encode(`event: error\ndata: ${JSON.stringify({ error: { message: streamError || "Upstream stream closed before completion" } })}\n\n`));
      }
      controller.enqueue(encoder.encode(converter.finish()));
      controller.enqueue(encoder.encode(sseDone()));
      controller.close();
    },
  });
  return new Response(stream, { headers: SSE_HEADERS });
}

function normalizeArgsForCodex(value) {
  if (value === undefined || value === null) return "{}";
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return "{}";
    try {
      JSON.parse(trimmed);
      return trimmed;
    } catch {
      return "{}";
    }
  }
  if (typeof value === "object") {
    try {
      const s = JSON.stringify(value);
      if (s) {
        JSON.parse(s);
        return s;
      }
    } catch {}
    return "{}";
  }
  return "{}";
}

function mapResponsesItemForCodex(item, toolNames, customNames) {
  if (!item || typeof item !== "object") return item;
  const t = item.type;
  if (t !== "function_call" && t !== "custom_tool_call") return item;
  let name = item.name;
  let callId = item.call_id || item.id;
  let rawArgs = item.arguments;
  if (typeof rawArgs !== "string" && rawArgs !== undefined && rawArgs !== null && typeof rawArgs === "object") {
    try {
      rawArgs = JSON.stringify(rawArgs);
    } catch {
      rawArgs = "";
    }
  }
  let args = typeof rawArgs === "string" ? rawArgs : typeof item.input === "string" ? item.input : "";
  // If upstream returned flat name (collaboration__spawn_agent), map to namespaced for Codex
  const mapped = toolNames instanceof Map ? toolNames.get(name) : undefined;
  const fallback = !mapped ? mapToolName(name) : undefined;
  const target = mapped || fallback;
  if (target) {
    name = target.name;
    item = { ...item, name, namespace: target.namespace };
  }
  // Custom tools: Codex expects custom_tool_call with raw input, not function_call with JSON
  const isCustom = customNames instanceof Set && customNames.has(name);
  if (isCustom) {
    const raw = item.type === "custom_tool_call" ? item.input : unwrapCustomToolArguments(args);
    return {
      id: callId,
      type: "custom_tool_call",
      status: item.status || "completed",
      call_id: callId,
      name,
      input: raw,
    };
  }
  if (t === "custom_tool_call" && !isCustom) {
    // Upstream mistakenly returned custom for a non-custom tool — normalize to function_call
    let normalized;
    if (typeof item.input === "string") {
      const trimmed = item.input.trim();
      if (!trimmed) normalized = "{}";
      else {
        try {
          JSON.parse(trimmed);
          normalized = trimmed;
        } catch {
          normalized = JSON.stringify({ content: item.input });
          try {
            JSON.parse(normalized);
          } catch {
            normalized = "{}";
          }
        }
      }
    } else {
      normalized = normalizeArgsForCodex(args);
    }
    return {
      id: callId,
      type: "function_call",
      status: item.status || "completed",
      call_id: callId,
      name,
      arguments: normalized,
      ...(item.namespace ? { namespace: item.namespace } : target ? { namespace: target.namespace } : {}),
    };
  }
  // Ensure function_call has arguments string
  if (isCustom) return item;
  return {
    ...item,
    name,
    arguments: normalizeArgsForCodex(args),
    ...(target && !item.namespace ? { namespace: target.namespace } : {}),
  };
}

function transformResponsesJsonForCodex(json, { toolNames, customNames, requestedModel, requestBytes }) {
  if (!json || typeof json !== "object") return json;
  json.model = requestedModel;
  if (Array.isArray(json.output)) {
    json.output = json.output.map((item) => {
      if (!item || typeof item !== "object") return item;
      if (item.type === "function_call" || item.type === "custom_tool_call") {
        return mapResponsesItemForCodex(item, toolNames, customNames);
      }
      // Some providers nest tool calls inside message content? Not for Responses.
      return item;
    });
  }
  if (!json.usage) {
    // Lazy fallback — caller will finalize if needed; keep shape for finalizeUsage
    json.usage = null;
  }
  return json;
}

async function streamResponsesTurn(upstream, { model, requestBytes, toolNames, customNames }) {
  const encoder = new TextEncoder();
  const decoder = new TextDecoder();
  // We need to rewrite tool names on the fly while proxying raw SSE.
  // Responses SSE is `event: <type>\ndata: <json>\n\n` — we parse each block, map tool items, re-emit.
  const reader = upstream.body.getReader();
  let buffer = "";
  let sawCompleted = false;
  let streamError = null;
  const stream = new ReadableStream({
    async start(controller) {
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          let idx;
          while ((idx = buffer.indexOf("\n\n")) >= 0) {
            const block = buffer.slice(0, idx);
            buffer = buffer.slice(idx + 2);
            if (!block.trim()) continue;
            const lines = block.split("\n");
            let event = "";
            let data = "";
            for (const line of lines) {
              if (line.startsWith("event:")) event = line.slice(6).trim();
              else if (line.startsWith("data:")) data = line.slice(5).trimStart();
            }
            if (!data || data === "[DONE]") {
              if (data === "[DONE]") controller.enqueue(encoder.encode("data: [DONE]\n\n"));
              continue;
            }
            let parsed;
            try {
              parsed = JSON.parse(data);
            } catch {
              controller.enqueue(encoder.encode(`event: ${event || "message"}\ndata: ${data}\n\n`));
              continue;
            }
            // Map tool call items in output_item events
            if (
              (event === "response.output_item.added" || event === "response.output_item.done") &&
              parsed.item &&
              (parsed.item.type === "function_call" || parsed.item.type === "custom_tool_call")
            ) {
              parsed.item = mapResponsesItemForCodex(parsed.item, toolNames, customNames);
              if (parsed.item.type === "function_call" && parsed.item.namespace) {
                // Codex expects namespaced function_call to carry namespace alongside name
                parsed.item.namespace = parsed.item.namespace;
              }
            }
            // Also handle response.completed's output array (some providers send it as event data)
            if (event === "response.completed" && parsed.response && Array.isArray(parsed.response.output)) {
              sawCompleted = true;
              parsed.response.output = parsed.response.output.map((it) => mapResponsesItemForCodex(it, toolNames, customNames));
              parsed.response.model = model;
            }
            if (event === "response.completed") sawCompleted = true;
            // Rewrite model in response.created/in_progress if present
            if ((event === "response.created" || event === "response.in_progress") && parsed.response) {
              parsed.response.model = model;
            }
            const outData = JSON.stringify(parsed);
            if (event) controller.enqueue(encoder.encode(`event: ${event}\ndata: ${outData}\n\n`));
            else controller.enqueue(encoder.encode(`data: ${outData}\n\n`));
          }
        }
        // Flush remainder
        if (buffer.trim()) {
          const lines = buffer.split("\n");
          let event = "";
          let data = "";
          for (const line of lines) {
            if (line.startsWith("event:")) event = line.slice(6).trim();
            else if (line.startsWith("data:")) data = line.slice(5).trimStart();
          }
          if (data && data !== "[DONE]") {
            try {
              let parsed = JSON.parse(data);
              if (parsed.item) parsed.item = mapResponsesItemForCodex(parsed.item, toolNames, customNames);
              if (parsed.response) sawCompleted = true;
              controller.enqueue(encoder.encode(`event: ${event}\ndata: ${JSON.stringify(parsed)}\n\n`));
            } catch {
              controller.enqueue(encoder.encode(buffer));
            }
          }
        }
      } catch (e) {
        streamError = e && e.message ? e.message : String(e);
        debugLog({ dir: "stream_error", wire: "responses", model, message: streamError });
      }
      if (streamError || !sawCompleted) {
        // Let client know the stream was truncated rather than pretending it completed cleanly
        const msg = streamError || "Upstream stream closed before response.completed";
        debugLog({ dir: "stream_aborted", wire: "responses", model, sawCompleted, message: msg });
        controller.enqueue(encoder.encode(`event: error\ndata: ${JSON.stringify({ error: { message: msg } })}\n\n`));
      }
      controller.enqueue(encoder.encode(sseDone()));
      controller.close();
    },
  });
  return new Response(stream, { headers: SSE_HEADERS });
}

export function createServer(config, secret) {
  const prefix = config.gateway.pathPrefix;

  return Bun.serve({
    port: config.gateway.port,
    websocket: {
      open() {},
      message() {},
      close() {},
      drain() {},
    },
    async fetch(request) {
      const url = new URL(request.url);
      const apiPath = apiPathFrom(url, prefix, secret);
      if (apiPath === "health") {
        return json({ ok: true, service: "codextras" });
      }
      if (apiPath === undefined) {
        return json({ error: { message: "not found" } }, 404);
      }
      if ((request.headers.get("upgrade") || "").toLowerCase() === "websocket") {
        // Codex probes a WebSocket transport first and retries on 405; a 426
        // refusal makes it fall back to HTTP streaming immediately.
        return new Response(null, { status: 426, headers: { Connection: "close" } });
      }
      const blocked = guard(request);
      if (blocked) {
        const message =
          blocked === 403
            ? "Browser-originated requests are not accepted by codextras."
            : "codextras requests require Content-Type: application/json.";
        return json({ error: { message } }, blocked);
      }
      if (request.method === "GET" && apiPath === "/v1/models") {
        const merged = mergeCatalog(config);
        return json({
          object: "list",
          data: merged.models.map((m) => ({
            id: m.slug || m.alias,
            object: "model",
            owned_by: "codextras",
            display_name: m.display_name || m.displayName || m.slug,
          })),
        });
      }
      if (request.method !== "POST") {
        return json({ error: { message: "method not allowed" } }, 405);
      }
      const rawBody = await request.arrayBuffer().catch(() => new ArrayBuffer(0));
      let payload;
      try {
        payload = JSON.parse(new TextDecoder().decode(rawBody));
      } catch {
        payload = undefined;
      }
      if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
        return json({ error: { message: "Request body must be a JSON object." } }, 400);
      }
      const inputs = Array.isArray(payload.input) ? payload.input : [];
      const compactionV2 =
        inputs.length > 0 && inputs[inputs.length - 1]?.type === "compaction_trigger";
      if (apiPath === "/v1/responses/compact" || compactionV2) {
        return handleCompaction(request, payload, apiPath, rawBody);
      }
      if (apiPath === "/v1/responses") {
        return handleTurn(request, payload, apiPath, rawBody);
      }
      return json({ error: { message: "unknown route " + apiPath } }, 404);
    },
  });
}

async function handleTurn(request, payload, apiPath, rawBody) {
  const model = findModel(payload.model, loadConfig());
  if (!model) {
    // Undeclared models are native OpenAI models: pass the request through.
    return forwardNative(request, apiPath, rawBody);
